DROP PROCEDURE IF EXISTS `Mem_Code_Order_Sto`$$
CREATE PROCEDURE `Mem_Code_Order_Sto`(IN p_Code VARCHAR(20), INOUT p_ouototal VARCHAR(50), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_orderidcard VARCHAR(14) DEFAULT NULL;
  DECLARE v_temp VARCHAR(50) DEFAULT NULL;
  SET p_ReturnValue = 0;
  IF p_ouototal IS NULL THEN SET p_ouototal = ''; END IF;
  IF (SELECT LEFT(`codenumber`, 8) FROM `Mem_Code` WHERE `code` = p_Code) = (SELECT LEFT(DATE_FORMAT(NOW(3), '%Y%m%d'), 8)) THEN
    UPDATE `Mem_Code` SET `codenumber` = `codenumber` + 1 WHERE `code` = p_Code;
  ELSE
    SET v_orderidcard = CONCAT((CAST((SELECT LEFT(DATE_FORMAT(NOW(3), '%Y%m%d'), 8)) AS CHAR(50))), '00001');
    UPDATE `Mem_Code` SET `codenumber` = v_orderidcard WHERE `code` = p_Code;
  END IF;
  SELECT `codenumber` INTO p_ouototal FROM (SELECT * FROM `Mem_Code` WHERE `code` = p_Code) AS `output` LIMIT 1;
END$$

DROP PROCEDURE IF EXISTS `Mem_Code_Sto`$$
CREATE PROCEDURE `Mem_Code_Sto`(IN p_code VARCHAR(50), INOUT p_ouototal VARCHAR(50), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_oldid BIGINT DEFAULT NULL;
  DECLARE v_newid BIGINT DEFAULT NULL;
  SET p_ReturnValue = 0;
  IF p_ouototal IS NULL THEN SET p_ouototal = ''; END IF;
  SELECT `codenumber` INTO v_oldid FROM `Mem_Code` WHERE `code` = p_code LIMIT 1;
  IF v_oldid < 0 THEN
    INSERT INTO `Mem_Code` (`code`, `codenumber`) VALUES (p_code, 0);
    SET v_oldid = 0;
  END IF;
  SET v_newid = 1 + v_oldid;
  SET p_ouototal = v_newid;
  UPDATE `Mem_Code` SET `codenumber` = p_ouototal WHERE `code` = p_code;
END$$

