DROP PROCEDURE IF EXISTS `Mem_UserInfo_SetPassword`$$
CREATE PROCEDURE `Mem_UserInfo_SetPassword`(IN p_ApplicationName VARCHAR(256), IN p_UserName VARCHAR(256), IN p_NewPassword VARCHAR(128), IN p_PasswordSalt VARCHAR(128), IN p_CurrentTimeUtc DATETIME(3), IN p_PasswordFormat INT, OUT p_ReturnValue INT)
proc: BEGIN
