  SET p_ReturnValue = 0;
  IF p_PasswordFormat IS NULL THEN SET p_PasswordFormat = 0; END IF;
  SET v_UserId = NULL;
  SELECT `u`.`UserId` INTO v_UserId FROM `Mem_Application` AS `A`, `Mem_Users` AS `U`, `Mem_UserInfo` AS `I` WHERE `A`.`ApplicationId` = `U`.`ApplicationId` AND `U`.`LowerName` = LOWER(p_UserName) AND LOWER(p_ApplicationName) = `A`.`LowerApplicationName` AND `U`.`UserId` = `I`.`UserId` LIMIT 1;
  IF (v_UserId IS NULL) THEN
    SET p_ReturnValue = (1);
    LEAVE proc;
  END IF;
  UPDATE `Mem_UserInfo` SET `Password` = p_NewPassword, `PasswordFormat` = p_PasswordFormat, `PasswordSalt` = p_PasswordSalt, `LastPasswordChangeDate` = p_CurrentTimeUtc WHERE v_UserId = `UserId`;
  SET p_ReturnValue = (0);
  LEAVE proc;
END$$

