CREATE PROCEDURE `Mem_UserRight_Save`(IN p_ApplicationName VARCHAR(512), IN p_UserID INT, IN p_RightsId INT, IN p_op VARCHAR(50), INOUT p_ouototal VARCHAR(50), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_ApplicationId INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  IF p_ouototal IS NULL THEN SET p_ouototal = ''; END IF;
