DROP PROCEDURE IF EXISTS `Mem_Users_Accede`$$
CREATE PROCEDURE `Mem_Users_Accede`(IN p_ApplicationName VARCHAR(256), IN p_UserName VARCHAR(256), IN p_Password VARCHAR(256), INOUT p_UserId INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_ApplicationId INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT `ApplicationId` INTO v_ApplicationId FROM `Mem_Application` WHERE `ApplicationName` = p_ApplicationName LIMIT 1;
  SELECT `A`.`UserId` INTO p_UserId FROM `Mem_Users` AS `A` LEFT JOIN `Mem_UserInfo` AS `B` ON `A`.`ApplicationId` = `B`.`ApplicationId` AND `A`.`UserId` = `B`.`UserId` WHERE `A`.`ApplicationId` = v_ApplicationId AND `A`.`UserName` = p_UserName AND `B`.`Password` = p_Password LIMIT 1;
  IF IFNULL(p_UserId, '') <> 0 THEN
    UPDATE `Mem_UserInfo` SET `LastLoginDate` = NOW(3) WHERE `ApplicationId` = v_ApplicationId AND `UserId` = p_UserId;
    UPDATE `Mem_Users` SET `LoginTime` = `LoginTime` + 1 WHERE `ApplicationId` = v_ApplicationId AND `UserId` = p_UserId;
  END IF;
END$$

DROP PROCEDURE IF EXISTS `Mem_Users_CreateUser`$$
CREATE PROCEDURE `Mem_Users_CreateUser`(IN p_ApplicationName VARCHAR(200), IN p_UserName VARCHAR(256), IN p_password VARCHAR(256), IN p_email VARCHAR(256), IN p_PasswordFormat INT, IN p_PasswordSalt VARCHAR(128), IN p_UserSex TINYINT(1), INOUT p_UserId INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_LastActivityDate DATETIME(3) DEFAULT NULL;
  DECLARE v_Count INT DEFAULT NULL;
  DECLARE v_ApplicationId INT DEFAULT NULL;
  DECLARE v__rv INT DEFAULT 0;
  SET p_ReturnValue = 0;
  SET v_LastActivityDate = NOW(3);
  SET v_Count = 0;
  SELECT COUNT(*) INTO v_Count FROM `Mem_Application_User` WHERE `LowerApplicationName` = LOWER(p_ApplicationName) AND `UserName` = p_UserName LIMIT 1;
  IF v_Count <> 0 THEN
    SET p_ReturnValue = -1;
    LEAVE proc;
  END IF;
  CALL `Mem_Code_Sto`('user', p_UserId, v__rv);
  SELECT `ApplicationId` INTO v_ApplicationId FROM `Mem_Application` WHERE `LowerApplicationName` = LOWER(p_ApplicationName) LIMIT 1;
  INSERT INTO `Mem_Users` (`ApplicationId`, `UserId`, `UserName`, `LowerName`, `LastActivityDate`) VALUES (v_ApplicationId, p_UserId, p_UserName, LOWER(p_UserName), v_LastActivityDate);
  INSERT INTO `Mem_UserInfo` (`ApplicationId`, `UserId`, `Password`, `PasswordFormat`, `PasswordSalt`, `Email`, `CreateDate`, `UserSex`) VALUES (v_ApplicationId, p_UserId, p_password, p_PasswordFormat, p_PasswordSalt, p_email, v_LastActivityDate, p_UserSex);
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `Mem_Users_Delete`$$
CREATE PROCEDURE `Mem_Users_Delete`(IN p_ApplicationName VARCHAR(200), IN p_UserId INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_ApplicationId INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT `ApplicationId` INTO v_ApplicationId FROM `Mem_Application` WHERE `ApplicationName` = p_ApplicationName LIMIT 1;
  DELETE FROM `Mem_UserInfo` WHERE `ApplicationId` = v_ApplicationId AND `UserId` = p_UserId;
  DELETE FROM `Mem_Users` WHERE `ApplicationId` = v_ApplicationId AND `UserId` = p_UserId;
  DELETE FROM `Mem_UserRight` WHERE `ApplicationId` = v_ApplicationId AND `UserId` = p_UserId;
END$$

DROP PROCEDURE IF EXISTS `Pay_Card_Info`$$
CREATE PROCEDURE `Pay_Card_Info`(IN p_OrderId VARCHAR(20), OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  SELECT * FROM `Pay_Card` WHERE `OrderId` = p_OrderId LIMIT 1;
END$$

DROP PROCEDURE IF EXISTS `Pay_Card_Lost`$$
CREATE PROCEDURE `Pay_Card_Lost`(IN p_OrderId VARCHAR(20), IN p_CardId VARCHAR(20), IN p_CardPassword VARCHAR(20), IN p_ApplicationId VARCHAR(20), INOUT p_ouototal VARCHAR(50), OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  IF p_ouototal IS NULL THEN SET p_ouototal = ''; END IF;
  SELECT COUNT(*) INTO p_ouototal FROM `Pay_Card` WHERE `ApplicationId` = p_ApplicationId AND `CardId` = p_CardId AND `CardPassword` = p_CardPassword AND `BeginDay` <= NOW(3) AND NOW(3) <= `EndDay` AND `IsValues` = 1 AND `IsOpen` = 1 LIMIT 1;
  IF (p_ouototal = 1) THEN
    UPDATE `Pay_Card` SET `IsValues` = 0, `OrderId` = p_OrderId WHERE `ApplicationId` = p_ApplicationId AND `CardId` = p_CardId AND `CardPassword` = p_CardPassword;
  END IF;
END$$

DROP PROCEDURE IF EXISTS `Pay_Info_Create`$$
CREATE PROCEDURE `Pay_Info_Create`(IN p_OrderId VARCHAR(20), IN p_OrderNumbers INT, IN p_OrderMoney DECIMAL(18,2), IN p_PayUserId VARCHAR(50), IN p_EnterIp VARCHAR(50), IN p_BuyInfo VARCHAR(200), IN p_IsPass INT, IN p_UserId VARCHAR(50), IN p_PayWay VARCHAR(20), IN p_op VARCHAR(50), INOUT p_ouototal VARCHAR(50), OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  IF p_ouototal IS NULL THEN SET p_ouototal = ''; END IF;
  IF (p_op = 'Insert') THEN
    INSERT INTO `Pay_Info` (`OrderId`, `OrderNumbers`, `OrderMoney`, `PayUserId`, `EnterIp`, `EnterDate`, `BuyInfo`, `IsPass`, `UserId`, `PayWay`) VALUES (p_OrderId, p_OrderNumbers, p_OrderMoney, p_PayUserId, p_EnterIp, NOW(3), p_BuyInfo, p_IsPass, p_UserId, p_PayWay);
    SELECT LAST_INSERT_ID() AS `identity`;
    SET p_ouototal = LAST_INSERT_ID();
  END IF;
  IF (p_op <> 'Insert') THEN
    UPDATE `Pay_Info` SET `OrderId` = p_OrderId, `OrderNumbers` = p_OrderNumbers, `OrderMoney` = p_OrderMoney, `PayUserId` = p_PayUserId, `EnterIp` = p_EnterIp, `BuyInfo` = p_BuyInfo, `IsPass` = p_IsPass, `UserId` = p_UserId, `LastDateTime` = NOW(3), `PayWay` = p_PayWay WHERE (`id` = p_op);
    SET p_ouototal = p_op;
  END IF;
END$$

DROP PROCEDURE IF EXISTS `Pay_Info_Post`$$
CREATE PROCEDURE `Pay_Info_Post`(IN p_OrderId VARCHAR(20), OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  UPDATE `Pay_Info` SET `IsPass` = 1, `LastDateTime` = NOW(3) WHERE `OrderId` = p_OrderId AND `IsPass` = 0;
END$$

DROP PROCEDURE IF EXISTS `st_Changepassword`$$
CREATE PROCEDURE `st_Changepassword`(IN p_id INT, IN p_password VARCHAR(200), IN p_new_password VARCHAR(200), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_pass VARCHAR(200) DEFAULT NULL;
  SET p_ReturnValue = 0;
  SET v_pass = (SELECT `Password` FROM `Users` WHERE `ID` = p_id);
  IF (v_pass = p_password) THEN
    UPDATE `Users` SET `Password` = p_new_password WHERE `ID` = p_id;
    SET p_ReturnValue = ROW_COUNT();
    LEAVE proc;
  ELSE
    SET p_ReturnValue = -1;
    LEAVE proc;
  END IF;
END$$

DROP PROCEDURE IF EXISTS `st_Forgotpassword`$$
CREATE PROCEDURE `st_Forgotpassword`(IN p_email VARCHAR(200), IN p_UserName VARCHAR(32), IN p_new_password VARCHAR(200), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_ch_Email VARCHAR(200) DEFAULT NULL;
  SET p_ReturnValue = 0;
  SET v_ch_Email = (SELECT `Email` FROM `Users` WHERE `Username` = p_UserName);
  IF (v_ch_Email = p_email) THEN
    UPDATE `Users` SET `Password` = p_new_password WHERE `Username` = p_UserName;
    SET p_ReturnValue = ROW_COUNT();
    LEAVE proc;
  ELSE
    SET p_ReturnValue = -1;
    LEAVE proc;
  END IF;
END$$

DROP PROCEDURE IF EXISTS `st_GetUserInfo`$$
CREATE PROCEDURE `st_GetUserInfo`(IN p_id INT, OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  SELECT * FROM `Users` WHERE `ID` = p_id;
END$$

DROP PROCEDURE IF EXISTS `st_GetUserName`$$
CREATE PROCEDURE `st_GetUserName`(IN p_Username VARCHAR(32), OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  SELECT * FROM `Users` WHERE `Username` = p_Username;
END$$

DROP PROCEDURE IF EXISTS `st_Login`$$
CREATE PROCEDURE `st_Login`(IN p_username VARCHAR(32), IN p_password VARCHAR(200), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_id INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SET v_id = (SELECT `ID` FROM `Users` WHERE `Username` = p_username AND `Password` = p_password);
  IF (IFNULL(v_id, 0) > 0) THEN
    SET p_ReturnValue = v_id;
    LEAVE proc;
  ELSE
    SET p_ReturnValue = -1;
    LEAVE proc;
  END IF;
END$$

DROP PROCEDURE IF EXISTS `st_add_Account`$$
CREATE PROCEDURE `st_add_Account`(IN p_Username VARCHAR(32), IN p_Password VARCHAR(200), IN p_Email VARCHAR(200), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_count INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SELECT IFNULL(COUNT(*), 0) INTO v_count FROM `Users` WHERE `Username` = p_Username LIMIT 1;
  IF v_count <> 0 THEN
    SET p_ReturnValue = 5;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  INSERT INTO `Users` (`Username`, `Password`, `Email`, `Fullname`, `Address`) VALUES (CAST(p_Username AS CHAR(32)), CAST(p_Password AS CHAR(200)), CAST(p_Email AS CHAR(200)), CAST('none' AS CHAR(100)), CAST('none' AS CHAR(250)));
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
END$$

DELIMITER ;
